def get_arithmetic_operation():
    """Get the arithmetic operation from user input."""
    while True:
        operation = input("Enter the arithmetic operation (+, -, *, /): ").strip()
        if operation in ['+', '-', '*', '/']:
            return operation
        else:
            print("Invalid input. Please enter a valid arithmetic operation.")

def get_numbers():
    """Get two numbers from user input."""
    while True:
        try:
            num1 = float(input("Enter the first number: "))
            num2 = float(input("Enter the second number: "))
            return num1, num2
        except ValueError:
            print("Invalid input. Please enter numbers.")

def perform_arithmetic_operation(num1, num2, operation):
    """Perform the arithmetic operation and return the result."""
    if operation == '+':
        result = num1 + num2
    elif operation == '-':
        result = num1 - num2
    elif operation == '*':
        result = num1 * num2
    elif operation == '/':
        if num2 == 0:
            raise ValueError("Cannot divide by zero.")
        result = num1 / num2
    else:
        raise ValueError("Invalid arithmetic operation.")
    return result

def main():
    """Get user input, perform the arithmetic operation, and display the result."""
    operation = get_arithmetic_operation()
    num1, num2 = get_numbers()

    try:
        result = perform_arithmetic_operation(num1, num2, operation)
        print(f"{num1} {operation} {num2} = {result}")
    except ValueError as e:
        print(e)

if __name__ == "__main__":
